const express = require('express');
const cors = require('cors');
const mongoose = require('mongoose');
const { validationResult } = require('express-validator');
require('dotenv').config();

// Express setup
const app = express();
app.use(cors());
app.use(express.json());

// In-memory storage of todos
let todos = [];

// MongoDB connection (if needed, for additional persistence)
// mongoose.connect(process.env.MONGODB_URI || 'mongodb://localhost:27017/todo', {
//   useNewUrlParser: true,
//   useUnifiedTopology: true,
// });

// Helper function to generate a unique ID
function generateId() {
  return Math.random().toString(36).substr(2, 9);
}

// Validators
const validateTodo = [
  body('title').isString().trim().isLength({ min: 1, max: 100 }),
];

// CRUD endpoints

// GET /todos
app.get('/todos', async (req, res) => {
  const { completed } = req.query;
  if (completed !== undefined) {
    todos = todos.filter(todo => todo.completed === (completed === 'true'));
  }
  res.json(todos);
});

// GET /todos/:id
app.get('/todos/:id', (req, res) => {
  const id = req.params.id;
  const todo = todos.find(item => item.id === id);
  if (!todo) return res.status(404).json({ error: 'Todo not found' });
  res.json(todo);
});

// POST /todos
app.post('/todos', validateTodo, async (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    const { title } = req.body;
    const newTodo = {
      id: generateId(),
      title,
      completed: false,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    todos.push(newTodo);
    res.status(201).json(newTodo);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// PUT /todos/:id
app.put('/todos/:id', validateTodo, async (req, res) => {
  try {
    const id = req.params.id;
    const { title } = req.body;
    const todoIndex = todos.findIndex(item => item.id === id);
    if (todoIndex === -1) return res.status(404).json({ error: 'Todo not found' });
    const updatedTodo = {
      ...todos[todoIndex],
      title,
      updatedAt: new Date().toISOString(),
    };
    todos[todoIndex] = updatedTodo;
    res.json(updatedTodo);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// DELETE /todos/:id
app.delete('/todos/:id', async (req, res) => {
  const id = req.params.id;
  const todoIndex = todos.findIndex(item => item.id === id);
  if (todoIndex === -1) return res.status(404).json({ error: 'Todo not found' });
  todos.splice(todoIndex, 1);
  res.json({ message: 'Todo deleted successfully' });
});

// Export the app
module.exports = {
  app,
};
