const request = require('supertest');
const app = require('./app');

describe('Todo List API', () => {
  before(() => {
    todos = [];
  });

  describe('/todos', () => {
    it('GET /todos should return all todos', async () => {
      const response = await request(app).get('/todos');
      expect(response.status).toBe(200);
      expect(Array.isArray(response.body)).toBe(true);
    });

    it('GET /todos/:id should return single todo', async () => {
      const todo1 = { id: generateId(), title: 'Todo 1' };
      todos.push(todo1);
      const response = await request(app).get(`/todos/${todo1.id}`);
      expect(response.status).toBe(200);
      expect(response.body).toEqual(todo1);
    });

    it('POST /todos should create a new todo', async () => {
      const response = await request(app)
        .post('/todos')
        .send({ title: 'Todo 2' });
      expect(response.status).toBe(201);
      expect(response.body.title).toBe('Todo 2');
    });

    it('PUT /todos/:id should update a todo', async () => {
      const todo = { id: generateId(), title: 'Todo 3' };
      todos.push(todo);
      const response = await request(app)
        .put(`/todos/${todo.id}`)
        .send({ title: 'Updated Todo' });
      expect(response.status).toBe(200);
      expect(response.body.title).toBe('Updated Todo');
    });

    it('DELETE /todos/:id should delete a todo', async () => {
      const todo = { id: generateId(), title: 'Todo 4' };
      todos.push(todo);
      const response = await request(app).delete(`/todos/${todo.id}`);
      expect(response.status).toBe(200);
      expect(response.body.message).toBe('Todo deleted successfully');
    });
  });

  describe('/todos validation', () => {
    it('POST /todos should return error for missing title', async () => {
      const response = await request(app)
        .post('/todos')
        .send({});
      expect(response.status).toBe(400);
      expect(Array.isArray(response.body.errors)).toBe(true);
      expect(response.body.errors[0].msg).toContain('required');
    });

    it('POST /todos should return error for invalid title', async () => {
      const response = await request(app)
        .post('/todos')
        .send({ title: 'A'.repeat(101) });
      expect(response.status).toBe(400);
      expect(Array.isArray(response.body.errors)).toBe(true);
      expect(response.body.errors[0].msg).toContain('string with length between 1 and 100');
    });
  });
});
